am_name` AS `target_team`,`p`.`player_name` AS `player_name`,`p`.`current_team` AS `current_team`,`s`.`salary` AS `salary`,round(((((((((case when (`t`.`def_rtg_weakness` = 1) then (`p`.`def_rtg_score` * 0.20) else 0 end) + (case when (`t`.`dreb_weakness` = 1) then ((`p`.`dreb_score` * 0.10) + (`p`.`dreb_pct_score` * 0.15)) else 0 end)) + (case when (`t`.`stl_weakness` = 1) then ((`p`.`stl_score` * 0.10) + (`p`.`stl_pct_score` * 0.15)) else 0 end)) + (case when (`t`.`blk_weakness` = 1) then ((`p`.`blk_score` * 0.10) + (`p`.`blk_pct_score` * 0.15)) else 0 end)) + (case when (`t`.`turnover_weakness` = 1) then (`p`.`stl_pct_score` * 0.05) else 0 end)) + (case when (`t`.`second_chance_weakness` = 1) then (`p`.`dreb_pct_score` * 0.05) else 0 end)) + (case when (`t`.`fast_break_weakness` = 1) then (`p`.`stl_pct_score` * 0.05) else 0 end)) + (case when (`t`.`paint_weakness` = 1) then (`p`.`blk_pct_score` * 0.05) else 0 end)),2) AS `match_score` from ((`team_needs` `t` join `player_profile` `p`) left join `salaries` `s` on((`p`.`player_name` = `s`.`player_name`))) where ((`p`.`current_team` <> `t`.`team_name`) and (`s`.`salary` is not null) and (`s`.`salary` > 0))) select `player_match`.`target_team` AS `target_team`,`player_match`.`player_name` AS `player_name`,`player_match`.`current_team` AS `current_team`,round((`player_match`.`salary` / 1000000),2) AS `salary_millions`,`player_match`.`match_score` AS `match_score`,round((`player_match`.`match_score` / (`player_match`.`salary` / 1000000)),2) AS `value_score` from `player_match` where (`player_match`.`match_score` > 0) */;
